import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Pb {

    private static List<String> arr = new ArrayList<>();
    private static StringBuilder word = new StringBuilder();
    private static int cont = 0;
    private static int mayor = 0;
    private static boolean flg = false;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int tam = Integer.parseInt(br.readLine());
        String cad = br.readLine();

        for (int i = 0; i < tam; i++) {
            process(cad.charAt(i), i, tam);
        }

        System.out.println(mayor + " " + arr.size());
    }

    private static void process(char ch, int index, int total) {
        if (ch == '(') {
            resetOutsideLength();
            flg = true;
        } else if (ch == ')') {
            flg = false;
            flushWord();
        } else if (flg) {
            if (ch != '_') {
                word.append(ch);
            } else {
                flushWord();
            }
        } else if (ch != '_') {
            cont++;
            if (index == total - 1 && cont >= mayor) {
                mayor = cont;
            }
        } else {
            resetOutsideLength();
        }
    }

    private static void resetOutsideLength() {
        if (cont >= mayor) {
            mayor = cont;
        }
        cont = 0;
    }

    private static void flushWord() {
        if (word.length() != 0) {
            arr.add(word.toString());
            word.setLength(0);
        }
    }
}
